package com.shopsphere;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;
@Entity @Table(name="orders")class OrderEntity{@Id UUID id;@Column(nullable=false,unique=true)String orderNumber;UUID userId;BigDecimal subtotal;BigDecimal discount;String couponCode;BigDecimal deliveryFee;BigDecimal totalAmount;@Enumerated(EnumType.STRING)Order.Status status;@Enumerated(EnumType.STRING)Order.PaymentStatus paymentStatus;String recipient;String addressLine1;String addressLine2;String city;String state;String postalCode;String country;String phone;Instant createdAt;Instant updatedAt;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)List<OrderItemEntity>items=new ArrayList<>();protected OrderEntity(){}OrderEntity(Order o){id=o.id();orderNumber=o.orderNumber();userId=o.userId();subtotal=o.subtotal();discount=o.discount();couponCode=o.couponCode();deliveryFee=o.deliveryFee();totalAmount=o.totalAmount();status=o.status();paymentStatus=o.paymentStatus();var a=o.shippingAddress();recipient=a.recipient();addressLine1=a.line1();addressLine2=a.line2();city=a.city();state=a.state();postalCode=a.postalCode();country=a.country();phone=a.phone();createdAt=o.createdAt();updatedAt=o.updatedAt();o.items().forEach(i->items.add(new OrderItemEntity(this,i)));}Order domain(){return new Order(id,orderNumber,userId,items.stream().map(OrderItemEntity::domain).toList(),subtotal,discount,couponCode,deliveryFee,totalAmount,status,paymentStatus,new Address(recipient,addressLine1,addressLine2,city,state,postalCode,country,phone),createdAt,updatedAt);}}
@Entity @Table(name="order_items")class OrderItemEntity{@Id UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_id",nullable=false)OrderEntity order;UUID productId;String productName;String sku;BigDecimal unitPrice;int quantity;BigDecimal lineTotal;protected OrderItemEntity(){}OrderItemEntity(OrderEntity o,OrderItem i){id=UUID.randomUUID();order=o;productId=i.productId();productName=i.productName();sku=i.sku();unitPrice=i.unitPrice();quantity=i.quantity();lineTotal=i.lineTotal();}OrderItem domain(){return new OrderItem(productId,productName,sku,unitPrice,quantity,lineTotal);}}
interface SpringOrderRepository extends JpaRepository<OrderEntity,UUID>{List<OrderEntity>findByUserIdOrderByCreatedAtDesc(UUID userId);}
@Repository class JpaOrderRepository implements OrderRepository{private final SpringOrderRepository data;JpaOrderRepository(SpringOrderRepository d){data=d;}public List<Order>findAll(int page,int size){return data.findAll(org.springframework.data.domain.PageRequest.of(Math.max(page,0),size,org.springframework.data.domain.Sort.by("createdAt").descending())).stream().map(OrderEntity::domain).toList();}public Order save(Order o){return data.saveAndFlush(new OrderEntity(o)).domain();}public Optional<Order>find(UUID id){return data.findById(id).map(OrderEntity::domain);}public List<Order>findByUser(UUID id){return data.findByUserIdOrderByCreatedAtDesc(id).stream().map(OrderEntity::domain).toList();}}
